// ─── SEARCH ENGINE ────────────────────────────────────────────────────────────
(function() {
  'use strict';

  let searchInput = null;
  let searchOverlay = null;
  let searchDebounce = null;

  // ── Tokenize query into lowercase words
  function tokenize(str) {
    return str.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(t => t.length > 1);
  }

  // ── Escape HTML special chars
  function escapeHtml(str) {
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  // ── Highlight matched tokens in text
  function highlight(text, tokens) {
    if (!text || !tokens.length) return escapeHtml(text || '');
    let result = escapeHtml(text);
    tokens.forEach(token => {
      const escaped = token.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      result = result.replace(new RegExp('(' + escaped + ')', 'gi'),
        '<mark class="search-highlight">$1</mark>');
    });
    return result;
  }

  // ── Extract a snippet around the first match
  function extractSnippet(text, tokens, maxLen) {
    if (!text) return '';
    const lower = text.toLowerCase();
    let pos = -1;
    for (const t of tokens) {
      pos = lower.indexOf(t);
      if (pos >= 0) break;
    }
    if (pos < 0) return text.substring(0, maxLen);
    const start = Math.max(0, pos - 60);
    const end = Math.min(text.length, start + maxLen);
    let snippet = text.substring(start, end);
    if (start > 0) snippet = '…' + snippet;
    if (end < text.length) snippet = snippet + '…';
    return snippet;
  }

  // ── Score an entry against query tokens
  function scoreEntry(entry, tokens) {
    const sectionLower = (entry.section || '').toLowerCase();
    const contentLower = (entry.content || '').toLowerCase();
    const titleLower   = (entry.title || '').toLowerCase();
    let score = 0;
    let matchedTokens = [];
    for (const token of tokens) {
      if (sectionLower.includes(token)) { score += 10; matchedTokens.push(token); }
      if (titleLower.includes(token))   { score += 8;  if (!matchedTokens.includes(token)) matchedTokens.push(token); }
      if (contentLower.includes(token)) { score += 3;  if (!matchedTokens.includes(token)) matchedTokens.push(token); }
    }
    // Bonus: all tokens matched
    if (matchedTokens.length === tokens.length) score += 5;
    return { score, matchedTokens };
  }

  // ── Perform full-text search
  function performSearch(query, maxResults) {
    maxResults = maxResults || 25;
    const tokens = tokenize(query);
    if (!tokens.length) return [];
    const scored = [];
    for (const entry of SEARCH_INDEX) {
      const { score, matchedTokens } = scoreEntry(entry, tokens);
      if (score > 0) scored.push({ entry, score, matchedTokens });
    }
    scored.sort((a, b) => b.score - a.score);
    // Deduplicate: keep best result per file+section
    const seen = new Set();
    const results = [];
    for (const r of scored) {
      const key = r.entry.file + '|' + r.entry.section;
      if (!seen.has(key)) {
        seen.add(key);
        results.push(r);
        if (results.length >= maxResults) break;
      }
    }
    return results;
  }

  // ── Create the overlay DOM element
  function createOverlay() {
    if (document.getElementById('oct-search-overlay')) return;
    searchOverlay = document.createElement('div');
    searchOverlay.id = 'oct-search-overlay';
    searchOverlay.innerHTML = `
      <div id="oct-search-inner">
        <div id="oct-search-header">
          <span id="oct-search-count"></span>
          <button id="oct-search-close" title="Close">✕</button>
        </div>
        <div id="oct-search-list"></div>
      </div>
    `;
    document.body.appendChild(searchOverlay);
    document.getElementById('oct-search-close').addEventListener('click', hideOverlay);
    document.addEventListener('keydown', e => { if (e.key === 'Escape') hideOverlay(); });
    document.addEventListener('click', e => {
      if (searchOverlay && searchOverlay.style.display !== 'none') {
        if (!searchOverlay.contains(e.target) &&
            !e.target.closest('#sidebar-search, .search-input')) {
          hideOverlay();
        }
      }
    });
  }

  // ── Position overlay below the search input
  function positionOverlay() {
    if (!searchInput || !searchOverlay) return;
    const rect = searchInput.getBoundingClientRect();
    const scrollY = window.scrollY || window.pageYOffset;
    if (window.innerWidth < 768) {
      searchOverlay.style.left = '0px';
      searchOverlay.style.width = '100vw';
      searchOverlay.style.top = (rect.bottom + scrollY + 4) + 'px';
    } else {
      const left = Math.max(0, rect.left);
      const width = Math.max(400, Math.min(520, window.innerWidth - left - 20));
      searchOverlay.style.left = left + 'px';
      searchOverlay.style.width = width + 'px';
      searchOverlay.style.top = (rect.bottom + scrollY + 4) + 'px';
    }
  }

  // ── Hide the overlay
  function hideOverlay() {
    if (searchOverlay) searchOverlay.style.display = 'none';
  }

  // ── Show search results
  function showResults(query) {
    if (!searchOverlay) createOverlay();
    const results = performSearch(query);
    const list = document.getElementById('oct-search-list');
    const countEl = document.getElementById('oct-search-count');
    const tokens = tokenize(query);

    if (!results.length) {
      list.innerHTML = `<div class="oct-no-results">
        <div style="font-size:28px;margin-bottom:8px">🔍</div>
        <div>No results for <strong>"${escapeHtml(query)}"</strong></div>
        <div style="font-size:12px;color:#94a3b8;margin-top:4px">Try different keywords</div>
      </div>`;
      countEl.textContent = '0 results';
    } else {
      countEl.textContent = results.length + ' result' + (results.length !== 1 ? 's' : '') + ' for "' + query + '"';
      list.innerHTML = results.map((r, i) => {
        const e = r.entry;
        const snippet = extractSnippet(e.content, r.matchedTokens, 200);
        const hlSnippet = highlight(snippet, r.matchedTokens);
        const hlSection = highlight(e.section, r.matchedTokens);
        const url = e.anchor ? e.file + '#' + e.anchor : e.file;
        const tagHtml = (e.tags || []).map(t =>
          `<span class="oct-tag oct-tag-${t}">${t}</span>`
        ).join('');
        return `<div class="oct-result${i===0?' oct-active':''}" data-url="${url}">
          <a href="${url}" class="oct-result-link">
            <div class="oct-result-meta">
              <span class="oct-ch-badge">Ch.${e.chapter}</span>
              <span class="oct-ch-title">${escapeHtml(e.title)}</span>
              <span class="oct-level oct-level-${(e.level||'').toLowerCase().replace(/\s+/g,'-')}">${e.level}</span>
              ${tagHtml}
            </div>
            <div class="oct-section">${hlSection}</div>
            <div class="oct-snippet">${hlSnippet}</div>
          </a>
        </div>`;
      }).join('');

      list.querySelectorAll('.oct-result').forEach(item => {
        item.addEventListener('click', () => {
          const a = item.querySelector('a');
          if (a) window.location.href = a.href;
        });
      });
    }

    positionOverlay();
    searchOverlay.style.display = 'block';
  }

  // ── Handle keyboard navigation in overlay
  function handleKeydown(e) {
    if (!searchOverlay || searchOverlay.style.display === 'none') return;
    const items = searchOverlay.querySelectorAll('.oct-result');
    const active = searchOverlay.querySelector('.oct-result.oct-active');
    let idx = active ? Array.from(items).indexOf(active) : -1;
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      if (active) active.classList.remove('oct-active');
      idx = Math.min(idx + 1, items.length - 1);
      items[idx]?.classList.add('oct-active');
      items[idx]?.scrollIntoView({ block: 'nearest' });
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      if (active) active.classList.remove('oct-active');
      idx = Math.max(idx - 1, 0);
      items[idx]?.classList.add('oct-active');
      items[idx]?.scrollIntoView({ block: 'nearest' });
    } else if (e.key === 'Enter') {
      e.preventDefault();
      const a = searchOverlay.querySelector('.oct-result.oct-active a');
      if (a) window.location.href = a.href;
    }
  }

  // ── Initialize search on all search inputs
  function initSearch() {
    createOverlay();
    const inputs = document.querySelectorAll('#sidebar-search, #global-search, .search-input');
    inputs.forEach(input => {
      searchInput = input;
      input.setAttribute('placeholder', 'Search all content…');
      input.addEventListener('input', e => {
        clearTimeout(searchDebounce);
        const q = e.target.value.trim();
        if (q.length < 2) { hideOverlay(); return; }
        searchDebounce = setTimeout(() => showResults(q), 180);
      });
      input.addEventListener('keydown', handleKeydown);
      input.addEventListener('focus', e => {
        if (e.target.value.trim().length >= 2) showResults(e.target.value.trim());
      });
    });
  }

  // Auto-init
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initSearch);
  } else {
    initSearch();
  }

})();
